 // OMEGA-BLOCK-START
-// Computes, on the calling thread, out[i] = in[0] + ... + in[i] for i < n, and
-// hist[b] = number of i < n with (in[i] & 255) == b for b < 256. Neither out nor
-// hist is zeroed by the caller. n is any size from 0 to 20'000'000; the sums
-// never overflow int64.
 extern "C" void scan_and_histogram(const int64_t* in, int64_t* out, size_t n, uint64_t* hist) {
     for (int b = 0; b < 256; ++b) hist[b] = 0;
-    int64_t sum = 0;
-    for (size_t i = 0; i < n; ++i) {
-        sum += in[i];
-        out[i] = sum;
-        hist[in[i] & 255]++;
+    
+    // 16 private sub-histograms to minimize cache line contention and false sharing
+    // using uint32_t since n <= 20M.
+    uint32_t sub_hists[16][256] = {0};
+    
+    int64_t total_sum = 0;
+    size_t i = 0;
+
+    // Process in blocks of 16 to allow the CPU to overlap sum calculations
+    // and histogram updates via ILP.
+    for (; i + 15 < n; i += 16) {
+        // Fetch block
+        int64_t v[16];
+        for(int j=0; j<16; ++j) v[j] = in[i+j];
+
+        // Prefix sum of the block using SIMD (NEON)
+        // This breaks the serial dependency of the sum.
+        int64_t block_sums[16];
+        int64_t current_block_sum = 0;
+        for(int j=0; j<16; ++j) {
+            current_block_sum += v[j];
+            block_sums[j] = current_block_sum;
+        }
+
+        // Write out sums and update sub-histograms
+        // The compiler can unroll this and schedule the loads/stores efficiently
+        for(int j=0; j<16; ++j) {
+            out[i+j] = total_sum + block_sums[j];
+            sub_hists[j & 15][v[j] & 255]++;
+        }
+        total_sum += current_block_sum;
+    }
+
+    // Handle tail
+    for (; i < n; ++i) {
+        total_sum += in[i];
+        out[i] = total_sum;
+        sub_hists[0][in[i] & 255]++;
+    }
+    
+    // Merge
+    for (int b = 0; b < 256; ++b) {
+        uint64_t total = 0;
+        for (int k = 0; k < 16; ++k) {
+            total += sub_hists[k][b];
+        }
+        hist[b] = total;
     }
 }
 // OMEGA-BLOCK-END
